select id, child_id, video_url, video_name, upload_doctor_id, is_deleted, create_time, update_time from video_resource WHERE is_deleted = 0
AND child_id = #{childId}
AND EXISTS (SELECT 1 FROM child_info c WHERE c.id = video_resource.child_id AND c.doctor_id = #{doctorId} AND c.is_deleted = 0)
ORDER BY ${sortField} ${sortOrder}
